draw_Figure_2<-function(){
 fl<-rd('Figure_2','Figure3b_fluorescence_observations');sf<-rd('Figure_2','Figure3b_fluorescence_summaries');fl$region<-factor(fl$region,levels=c('mature_zone','root_tip'),labels=c('Mature zone','Root tip'));sf$region<-factor(sf$region,levels=c('mature_zone','root_tip'),labels=c('Mature zone','Root tip'))
 pf<-ggplot(sf,aes(day,mean,colour=gravity))+geom_line(linewidth=.65)+geom_errorbar(aes(ymin=mean-se,ymax=mean+se),width=.13,linewidth=.4)+geom_point(size=1.8)+facet_wrap(~region,ncol=1)+scale_colour_manual(values=pal,labels=glab,breaks=names(pal))+scale_x_continuous(breaks=0:7)+labs(x='Day after inoculation',y='Mean RFP intensity (a.u.)')+theme(legend.position='none',panel.spacing=mm(4))
 d<-rd('Figure_2','Figure3c_cell_observations');u<-rd('Figure_2','Figure3c_cell_summaries');st<-rd('Figure_2','Figure3c_daywise_Welch_effects');d$gravity<-factor(d$gravity,levels=names(pal));d<-offset(d,c('gravity','day'),as.numeric(d$gravity));u$x<-match(u$gravity,names(pal));d$day_label<-factor(d$day,levels=c(3,7),labels=c('Day 3','Day 7'));u$day_label<-factor(u$day,levels=c(3,7),labels=c('Day 3','Day 7'))
 top<-max(d$cells_1e8_per_ml)*1.17
 pc<-ggplot(d,aes(x,cells_1e8_per_ml,colour=gravity))+geom_col(data=u,aes(x=x,y=mean,fill=gravity),inherit.aes=FALSE,width=.55,colour=unname(pal_dark[u$gravity]),linewidth=.6)+geom_point(size=1.9)+geom_errorbar(data=u,aes(x=x,y=mean,ymin=mean-se,ymax=mean+se),inherit.aes=FALSE,width=.12,linewidth=.5)+facet_wrap(~day_label,nrow=1)+scale_colour_manual(values=pal,guide='none')+scale_fill_manual(values=pal_fill,guide='none')+scale_x_continuous(breaks=1:2,labels=c('1 g','s\u03bcg'),limits=c(.55,2.45))+scale_y_continuous(limits=c(0,top*1.11),expand=expansion(mult=0))+labs(x=NULL,y=expression(Concentration~(10^8~cells~mL^{-1})))
 ann<-data.frame(day_label=factor(st$day,levels=c(3,7),labels=c('Day 3','Day 7')),x=1.5,y=top*1.02,label=paste0('q = ',qfmt(st$fdr)))
 ann$x1<-1;ann$x2<-2;ann$yb<-top;ann$ylow<-top*.975
 pc<-pc+geom_segment(data=ann,aes(x=x1,xend=x2,y=yb,yend=yb),inherit.aes=FALSE,linewidth=.35)+geom_segment(data=ann,aes(x=x1,xend=x1,y=yb,yend=ylow),inherit.aes=FALSE,linewidth=.35)+geom_segment(data=ann,aes(x=x2,xend=x2,y=yb,yend=ylow),inherit.aes=FALSE,linewidth=.35)+geom_text(data=ann,aes(x,y,label=label),inherit.aes=FALSE,vjust=0,size=3.2)
 export('Figure_2',190,184,function(){
  place(0,0,103,105,function(){header('a','Day-3 root\u2013bacterium imaging');txt('1 g',34,10,10,TRUE,col=blue,just='centre');txt('s\u03bcg',79,10,10,TRUE,col=orange,just='centre');fs<-c('stationary_mature','clinorotation_mature','stationary_tip','clinorotation_tip')
   for(i in 1:4){x<-if(i%%2==1)14 else 59;y<-if(i<3)18 else 59;im<-image_read(file.path(pkg,'assets/microscopy',paste0(fs[i],'.jpg')));inf<-image_info(im);h<-42*inf$height/inf$width;place(x,y,42,h,function(){grid.raster(as.raster(im),interpolate=TRUE);grid.segments(x0=.80,x1=.853,y0=.115,y1=.115,gp=gpar(col='white',lwd=2));grid.text('100 \u00b5m',x=.95,y=.035,just=c('right','bottom'),gp=gpar(col='white',fontsize=7,fontfamily=font))})};grid.text('Mature zone',x=mm(3),y=unit(1,'npc')-mm(35),rot=90,gp=gpar(fontfamily=font,fontsize=9));grid.text('Root tip',x=mm(3),y=unit(1,'npc')-mm(76),rot=90,gp=gpar(fontfamily=font,fontsize=9))})
  place(107,0,83,105,function()panel(pf,'b','Root-zone fluorescence',83,105));place(0,111,190,73,function()panel(pc,'c','Bacterial concentration in chip-channel liquid',190,73))
 })
}
draw_Figure_3<-function(){
 d<-rd('Figure_3','Figure3_all_growth_observations');s<-rd('Figure_3','Growth_traits_group_summaries');e<-rd('Figure_3','Growth_traits_average_inoculation_effects');e$q_value<-p.adjust(e$p_value,'BH');metrics<-unique(d$metric);plots<-list()
 for(k in 1:2){m<-metrics[c(2,3)[k]];x<-d[d$metric==m,];u<-s[s$metric==m,];x$bacteria<-factor(x$bacteria,levels=c('uninoculated','inoculated'));x$gravity<-factor(x$gravity,levels=names(pal));base<-as.numeric(x$bacteria)+ifelse(x$gravity==names(pal)[1],-.17,.17);x<-offset(x,c('bacteria','gravity'),base,.055);u$x<-match(u$bacteria,c('uninoculated','inoculated'))+ifelse(u$gravity==names(pal)[1],-.17,.17);z<-e[e$metric==m,];top<-max(x$value)*1.18
  p<-ggplot(x,aes(x,value,colour=gravity))+geom_col(data=u,aes(x=x,y=mean,fill=gravity),inherit.aes=FALSE,width=.29,colour=unname(pal_dark[u$gravity]),linewidth=.6)+geom_point(size=1.8)+geom_errorbar(data=u,aes(x=x,y=mean,ymin=mean-se,ymax=mean+se),inherit.aes=FALSE,width=.1,linewidth=.5)+scale_colour_manual(values=pal,labels=glab,breaks=names(pal))+scale_fill_manual(values=pal_fill,guide='none')+scale_x_continuous(breaks=1:2,labels=c('Uninoculated','Inoculated'),limits=c(.5,2.5))+scale_y_continuous(limits=c(0,top*1.12),expand=expansion(mult=0))+labs(x=NULL,y=if(k==1)'Root diameter (\u00b5m)'else'Leaf fresh weight (mg)')+theme(legend.position='none')
  plots[[k]]<-bracket(p,1,2,top,paste0('q = ',qfmt(z$q_value)),top*.025)
 }
 s<-rd('shared/Conditioned_medium','main_curve_mean_SD_SE');s<-s[s$group!='LB_control',];cols<-c(pal,MS_control='#707070');labs<-c(stationary_1g='1 g-derived medium',clinorotation='s\u03bcg-derived medium',MS_control='Half-strength MS');yy<-range(c(s$mean-s$se,s$mean+s$se,0));yy<-yy+c(-1,1)*diff(yy)*.07
 curve<-function(day)ggplot(s[s$collection_day==day,],aes(time_h,mean,colour=group,fill=group))+geom_ribbon(aes(ymin=mean-se,ymax=mean+se),alpha=.30,colour=NA)+geom_line(linewidth=.7)+scale_colour_manual(values=cols,labels=labs)+scale_fill_manual(values=cols,labels=labs)+scale_x_continuous(breaks=c(0,24,48,72),limits=c(0,72),expand=expansion(mult=c(.01,.015)))+coord_cartesian(ylim=yy)+labs(x='Culture time (h)',y=expression('Corrected OD'[600]))+theme(legend.position='none')
 export('Figure_3',190,166,function(){place(0,0,94,77,function()panel(plots[[1]],'a','Mature-root diameter',94,77));place(98,0,92,77,function()panel(plots[[2]],'b','Leaf fresh weight',92,77));place(0,86,94,72,function()panel(curve(3),'c','Day-3 conditioned medium',94,72));place(98,86,92,72,function()panel(curve(7),'d','Day-7 conditioned medium',92,72));for(i in 1:3){x<-c(9,71,138)[i];grid.lines(x=mm(c(x,x+7)),y=unit(1,'npc')-mm(c(162,162)),gp=gpar(col=cols[i],lwd=1.7));txt(labs[i],x+9,160,8.5)}})
}
draw_Figure_S5a<-function(){
 d<-rd('shared/Conditioned_medium','all_well_corrected_OD');d$condition<-factor(d$group,levels=c(names(pal),'MS_control','LB_control'),labels=c('1 g medium','s\u03bcg medium','Half-strength MS','LB'));d$day<-factor(d$collection_day,levels=c(3,7),labels=c('Day 3','Day 7'))
 p<-ggplot(d,aes(time_h,od_corrected,group=interaction(collection_day,well)))+geom_line(aes(colour=included_main,linetype=included_main),linewidth=.45)+facet_wrap(vars(day,condition),ncol=4,scales='free_y')+scale_colour_manual(values=c('TRUE'=blue,'FALSE'='#B34A77'),labels=c('TRUE'='Inoculated assay well','FALSE'='Uninoculated E2 well'))+scale_linetype_manual(values=c('TRUE'='solid','FALSE'='22'),labels=c('TRUE'='Inoculated assay well','FALSE'='Uninoculated E2 well'))+scale_x_continuous(breaks=c(0,24,48,72))+labs(x='Culture time (h)',y=expression('Corrected OD'[600]))+theme(strip.text=element_text(size=9),axis.text=element_text(size=8),panel.spacing=mm(4))
 export('Figure_S5a',190,135,function()drawp(p))
}
draw_Figure_S5b<-function(){
 d<-rd('shared/Conditioned_medium','background_timepoint_summary');d$day<-factor(d$collection_day,levels=c(3,7),labels=c('Day 3','Day 7'))
 p<-ggplot(d,aes(time_h,blank_mean,colour=blank_group,fill=blank_group))+geom_ribbon(aes(ymin=blank_mean-blank_sd,ymax=blank_mean+blank_sd),alpha=.2,colour=NA)+geom_line(linewidth=.65)+facet_wrap(~day,nrow=1)+scale_colour_manual(values=c(LB_blank='#379783',MS_blank='#707070'),labels=c(LB_blank='LB',MS_blank='Half-strength MS'))+scale_fill_manual(values=c(LB_blank='#379783',MS_blank='#707070'),labels=c(LB_blank='LB',MS_blank='Half-strength MS'))+scale_x_continuous(breaks=c(0,24,48,72))+labs(x='Culture time (h)',y=expression(OD[600]))
 export('Figure_S5b',180,87,function()drawp(p))
}
